//! Command line argument handling.

/// Faithful reimplementation of C's `atoi`.
///
/// Skips leading whitespace, accepts an optional sign, consumes the leading run
/// of decimal digits and ignores the rest of the string. Values that overflow a
/// C `long` saturate at the `long` bounds (as `strtol` does) and are then
/// truncated to 32 bits, matching `atoi` on LP64 platforms — e.g. `4294967337`
/// yields `41`, and `99999999999999999999` yields `-1`.
pub fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut acc: i64 = 0;
    let mut saturated = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !saturated {
            let digit = (bytes[i] - b'0') as i64;
            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                Some(v) => acc = v,
                None => saturated = true,
            }
        }
        i += 1;
    }

    let value: i64 = if saturated {
        if negative {
            i64::MIN
        } else {
            i64::MAX
        }
    } else if negative {
        -acc
    } else {
        acc
    };

    value as i32
}

fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Reads the tooth count from the command line, defaulting to 11.
pub fn parse_n<I: Iterator<Item = String>>(args: I) -> i32 {
    let mut n = 11;
    let mut args = args;
    if let Some(arg) = args.nth(1) {
        n = atoi(&arg);
    }
    n
}
