//! Generation of the gear-shaped test polygon.

use std::f64::consts::PI;

/// Builds the gear outline: `n` teeth, alternating between a point on the unit
/// circle and a point at radius 0.7 halfway to the next tooth.
///
/// The returned polygon has a single ring, matching the C++ fixture.
pub fn gear_polygon(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut gear: Vec<[f64; 2]> = Vec::new();

    let mut i: i32 = 0;
    while i < n {
        let angle1 = 2.0 * PI * (i as f64) / (n as f64);
        let angle2 = 2.0 * PI * (i as f64 + 0.5) / (n as f64);

        gear.push([angle1.cos(), angle1.sin()]);
        gear.push([0.7 * angle2.cos(), 0.7 * angle2.sin()]);

        i += 1;
    }

    polygon.push(gear);
    polygon
}
